const KEY='redscore-bunker-entered-v1';
let entered=false;
try{entered=sessionStorage.getItem(KEY)==='yes';}catch{/* A blocked store still allows entry for this page. */}
export function showBunkerEntrance({language='de',route='home',modal=false}={}){
 if(entered||modal||!['home','public'].includes(route)||document.querySelector('.bunker-entry'))return;
 const en=language==='en';
 const gate=document.createElement('dialog');gate.className='bunker-entry';gate.setAttribute('aria-labelledby','bunker-title');
 gate.innerHTML=`<div class="bunker-wall" aria-hidden="true"></div><header class="bunker-brand"><img src="/assets/redscore-logo.png?v=5" alt=""><span><b>Red<span>Score</span></b><small>${en?'Because emergencies don’t ask if you’re ready.':'Weil der Ernstfall nicht fragt, ob du bereit bist.'}</small></span></header><div class="bunker-intro"><p>${en?'YOUR PERSONAL PREPAREDNESS PORTAL':'DEIN PERSÖNLICHES VORSORGEPORTAL'}</p><h1 id="bunker-title">${en?'Outside, uncertainty.':'Draußen Ungewissheit.'}<br><span>${en?'Inside, your preparation.':'Hier beginnt deine Vorsorge.'}</span></h1></div><div class="bunker-scene"><div class="bunker-lamp"></div><div class="bunker-frame"><div class="bunker-beyond"><img src="/assets/redscore-logo.png?v=5" alt=""><span>REDSCORE</span></div><div class="bunker-door"><span class="bunker-plate">REDSCORE <small>${en?'PERSONAL ACCESS':'PERSÖNLICHER ZUGANG'}</small></span><i class="bunker-hinge h1"></i><i class="bunker-hinge h2"></i><button type="button" class="bunker-wheel" aria-label="${en?'Turn the wheel and open the bunker door':'Drehrad drehen und Bunkertür öffnen'}"><i aria-hidden="true"></i><i aria-hidden="true"></i><i aria-hidden="true"></i><b aria-hidden="true"></b></button><div class="bunker-ribs"></div><span class="bunker-door-code">RS / 001</span></div></div><div class="bunker-floor"></div></div><div class="bunker-action"><button type="button" data-bunker-enter>${en?'Enter your bunker':'Deinen Bunker betreten'} <span aria-hidden="true">→</span></button><p role="status">${en?'Your supplies. Your responsibility. Your RedScore.':'Deine Vorräte. Deine Verantwortung. Dein RedScore.'}</p><button type="button" class="bunker-skip">${en?'Go straight to the portal':'Direkt zum Portal'}</button></div>`;
 let opening=false;
 const finish=()=>{gate.close();gate.remove();document.documentElement.classList.remove('bunker-active');document.querySelector('#app h1')?.setAttribute('tabindex','-1');document.querySelector('#app h1')?.focus({preventScroll:true});};
 const enter=(animate=true)=>{if(opening)return;opening=true;entered=true;try{sessionStorage.setItem(KEY,'yes');}catch{}gate.querySelector('[data-bunker-enter]').disabled=true;gate.querySelector('.bunker-wheel').disabled=true;gate.querySelector('[role=status]').textContent=en?'Opening your portal …':'Dein Portal öffnet sich …';if(!animate||matchMedia('(prefers-reduced-motion: reduce)').matches)return finish();gate.classList.add('is-opening');setTimeout(finish,1500);};
 gate.querySelector('.bunker-wheel').addEventListener('click',()=>enter());gate.querySelector('[data-bunker-enter]').addEventListener('click',()=>enter());gate.querySelector('.bunker-skip').addEventListener('click',()=>enter(false));gate.addEventListener('cancel',e=>{e.preventDefault();enter(false)});
 document.body.append(gate);document.documentElement.classList.add('bunker-active');gate.showModal();gate.querySelector('[data-bunker-enter]').focus();
}
